fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut low = lo;
    let mut high = hi;

    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

fn search_1000(a: &[i32], x: i32) -> usize {
    // We only consider the first 1000 elements
    let limit = 1000;
    search_range_helper(a, x, 0, limit)
}

